const F=n=>Number(n).toLocaleString('vi-VN',{maximumFractionDigits:2}),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),T=s=>String(s??'').replace(/[\uE000-\uF8FF]/g,'').replace(/\s+/g,' ').trim();
