function renderMapTasks(){const tasks=mapTaskRecords();sum.textContent=`${tasks.length} nhiệm vụ bản đồ · dữ liệu node thật · ưu tiên còn khả thi và gần nhất`;list.innerHTML=tasks.map(task=>{const tags=[task.kind];if(task.danger)tags.push(task.danger.label);if(task.row){const q=preview(task.row);if(!task.row.meta.combat.length)tags.push('Không cần chiến đấu');else if(!q)tags.push('Có chiến đấu · chưa dò được');else if(q.tuTran)tags.push('Tử địa');else if(q.thang&&q.ketQua?.thuongThe)tags.push('Thắng nhưng có thể bị thương');else if(q.thang)tags.push('Dễ thắng');else tags.push('Khó thắng')}if(N(task.remaining))tags.push(task.remaining>=0?`Còn ${fmtDuration(task.remaining)}`:`Quá hạn ${fmtDuration(-task.remaining)}`);if(task.state==='unreachable')tags.push('Không đến kịp');if(task.state==='expired')tags.push('Đã hết hạn');const data=task.action==='act'?`data-k="${E(task.key.slice(4))}"`:task.action==='random-act'?`data-random="${E(task.key)}"`:task.action==='place-act'?`data-place="${E(task.key)}"`:`data-quest="${E(task.key)}"`;return`<article ${data} data-slot="${E(task.slot||'')}"><div><div class="name">${E(task.name)}</div><div class="tags">${tags.map(x=>`<span class="tag ${x==='Không đến kịp'||x==='Đã hết hạn'||x==='Tử địa'?'bad':x==='An toàn'?'good':''}">${E(x)}</span>`).join('')}</div>${task.rewards?.length?`<div class="gain">Có thể được: ${E(task.rewards.join(' · '))}</div>`:''}</div><div class="travel">${N(task.travel)?`<strong>${fmtDuration(task.travel)}</strong><span>${fmtDistance(task.distance)}</span>`:'<strong>Chưa rõ</strong><span>vị trí</span>'}</div><div>${task.slot?`<button class="red ${task.action}">Xem trên bản đồ</button><button class="ghost safe-route-act">Đường an toàn</button>`:''}</div></article>`}).join('')||'<p>Không có nhiệm vụ bản đồ đang hoạt động.</p>'}
function renderPeople(){const run=g.state.run;sum.textContent=`${people.length} người trong nhân mạch · năm ${F(run.nam)} · ${W.info(run.viTri).ten}`;list.innerHTML=people.map(r=>{const tags=[r.relationName];if(r.realm!==null)tags.push(`Cảnh giới ${r.realm}`);if(r.faction)tags.push(r.faction);if(r.lastGiftYear===Math.floor(run.nam))tags.push('Đã tặng quà năm nay');const gift=r.giftKnown&&r.giftLike?`Quà thích: ${r.giftLikeName}`:'Chưa rõ quà yêu thích',canMap=Boolean(r.slot),canGift=Boolean(r.giftLike&&r.giftKnown);return`<article data-person="${E(r.key)}"><div><div class="name">${E(r.name)}</div><div class="tags">${tags.map(x=>`<span class="tag">${E(x)}</span>`).join('')}</div><div class="sub">Hảo cảm: ${r.affection===null?'?':F(r.affection)} · ${E(r.locationNote)}</div><div class="gain">${E(gift)}</div>${r.debt!==null?`<div class="risk">Nghĩa vụ / khoản nợ: ${F(r.debt)}</div>`:''}</div><div class="travel">${r.travelYears!==null?`<strong>${fmtDuration(r.travelYears)}</strong><span>${fmtDistance(r.distanceLi)}</span>`:'<strong>Chưa rõ</strong><span>vị trí</span>'}</div><div><div class="safe">${E(r.relationName)}</div>${canGift?'<button class="ghost gift-act">Tìm quà</button>':''}${canMap?'<button class="red person-act">Xem trên bản đồ</button>':''}</div></article>`}).join('')||'<p>Chưa có NPC đủ điều kiện hiển thị trong nhân mạch.</p>'}
